                                <h2 id="endpoints-POSTapi-mobile-register">Register a new standard user and send verification code.</h2>

<p>
</p>



<span id="example-requests-POSTapi-mobile-register">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/mobile/register" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "name=vmqeopfuudtdsufvyvddq"\
    --form "email=kunde.eloisa@example.com"\
    --form "password=4[*UyPJ"}6"\
    --form "password_confirmation=consequatur"\
    --form "phone=+256277171772"\
    --form "profile_image=@C:\Users\Syrian Technology\AppData\Local\Temp\php7E82.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/mobile/register"
);

const headers = {
    "Content-Type": "multipart/form-data",
