                    <h2 id="endpoints-PUTapi-mobile-me">Update mobile user&#039;s profile information.</h2>

<p>
</p>

<p>Accepts a file for profile_image (via POST with _method=PUT) or a standard JSON PUT.</p>

<span id="example-requests-PUTapi-mobile-me">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request PUT \
    "http://localhost/api/mobile/me" \
    --header "Content-Type: multipart/form-data" \
    --header "Accept: application/json" \
    --form "name=vmqeopfuudtdsufvyvddq"\
    --form "phone=amniihfqcoynlazghdtqt"\
    --form "profile_image=@C:\Users\Syrian Technology\AppData\Local\Temp\php83C2.tmp" </code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/mobile/me"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('name', 'vmqeopfuudtdsufvyvddq');
body.append('phone', 'amniihfqcoynlazghdtqt');
body.append('profile_image', document.querySelector('input[name="profile_image"]').files[0]);

fetch(url, {
    method: "PUT",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

